// Construye el payload del componente de métricas (servicio HTTP metrics).
// Las observaciones provienen de automation_log (datos reales del piloto).
const config = $('Configuración').first().json;
const filas = $input.first().json.rows ?? [];

const ejecuciones = filas.map((fila) => ({
  workflow_id: fila.workflow_id,
  timestamp_inicio:
    fila.timestamp_inicio instanceof Date
      ? fila.timestamp_inicio.toISOString()
      : fila.timestamp_inicio ?? null,
  estado: fila.estado,
  registros_procesados: Number(fila.registros_procesados ?? 0),
  latencia_ms:
    fila.latencia_ms === null || fila.latencia_ms === undefined
      ? null
      : Number(fila.latencia_ms),
}));

return [
  {
    json: {
      workflowId: 'todos',
      periodoInicio: config.periodo_inicio,
      periodoFin: config.periodo_fin,
      lineaBaseTiempoManualSegundos: Number(config.linea_base_tiempo_manual_segundos),
      lineaBaseTasaErrorManual: Number(config.linea_base_tasa_error_manual),
      umbralObservacionesMinimo: Number(config.umbral_observaciones_minimo),
      fuenteDatos: 'postgres',
      ejecuciones,
    },
  },
];

// Integra los indicadores de negocio (SQL) con el informe de métricas
// (componente metrics) y redacta el correo del reporte semanal.
const config = $('Configuración').first().json;
const indicadores = $('Consultar Indicadores Semana').first().json;
const respuestaMetricas = $('Invocar Métricas').first().json;

const contactosProcesados = Number(indicadores.contactos_procesados ?? 0);
const citasRegistradas = Number(indicadores.citas_registradas ?? 0);
const negociosCerrados = Number(indicadores.negocios_cerrados ?? 0);
const flujosFallidos = Number(indicadores.flujos_fallidos ?? 0);

const datos = respuestaMetricas.data ?? respuestaMetricas;
const m = datos.metricas ?? {};
const vd1 = datos.comparacionVD1 ?? {};
const vd2 = datos.comparacionVD2Registros ?? datos.comparacionVD2 ?? {};
const vd2Diagnostico = datos.comparacionVD2 ?? {};

const numero = (valor, decimales = 0) =>
  new Intl.NumberFormat('es-CO', {
    minimumFractionDigits: decimales,
    maximumFractionDigits: decimales,
  }).format(Number(valor ?? 0));

const lineas = [
  'REPORTE SEMANAL DE AUTOMATIZACIÓN FINTECH',
  `Periodo: ${config.periodo_etiqueta}`,
  '',
  'INDICADORES DE NEGOCIO',
  `- Contactos procesados (leads registrados en el CRM): ${numero(contactosProcesados)}`,
  `- Citas registradas (appointment en el periodo): ${numero(citasRegistradas)}`,
  `- Negocios cerrados (leads con estado=cliente): ${numero(negociosCerrados)}`,
  `- Flujos fallidos (ejecuciones con estado=error): ${numero(flujosFallidos)}`,
  '',
  'MÉTRICAS DE AUTOMATIZACIÓN (componente metrics · datos reales de PostgreSQL)',
  `- Ejecuciones medidas: ${numero(m.observaciones ?? 0)}`,
  `- Media de latencia: ${numero(m.mediaLatenciaMs ?? 0, 2)} ms`,
  `- Mediana de latencia: ${numero(m.medianaLatenciaMs ?? 0, 2)} ms`,
  `- Desviación estándar de latencia: ${numero(m.desviacionEstandarLatenciaMs ?? 0, 2)} ms`,
  `- Tasa de error por registro procesado (VD2): ${numero(m.tasaErrorRegistrosPorcentaje ?? 0, 2)} %`,
  `- Tasa de fallos por ejecución (diagnóstico): ${numero(m.tasaErrorPorcentaje ?? 0, 2)} %`,
  `- Total de registros procesados: ${numero(m.totalRegistrosProcesados ?? 0)}`,
  '',
  'VARIABLES DEPENDIENTES (§2.4 de la tesis)',
  `VD1 — Reducción del tiempo de sincronización: ${numero(vd1.porcentajeReduccion ?? 0, 2)} % (meta ≥ 70 %)`,
  `VD2 — Reducción de la tasa de errores: ${numero(vd2.porcentajeReduccion ?? 0, 2)} % (meta ≥ 50 %)`,
  `Línea base manual aplicada: ${numero(config.linea_base_tiempo_manual_segundos, 0)} s por operación · ${numero(config.linea_base_tasa_error_manual, 2)} % de error`,
  '',
  'Origen de los datos: REALES (automation_log y tablas del MER en PostgreSQL).',
];

if (datos.advertenciaPeriodoSinRegistros) {
  lineas.push('', `ADVERTENCIA: ${datos.advertenciaPeriodoSinRegistros}`);
}
if (datos.advertenciaDatosInsuficientes) {
  lineas.push('', `ADVERTENCIA: ${datos.advertenciaDatosInsuficientes}`);
}

return [
  {
    json: {
      destinatario: config.destinatario,
      remitente: config.remitente,
      asunto: `Reporte Semanal de Automatización Fintech — ${config.periodo_etiqueta}`,
      cuerpo: lineas.join('\n'),
      contactos_procesados: contactosProcesados,
      citas_registradas: citasRegistradas,
      negocios_cerrados: negociosCerrados,
      flujos_fallidos: flujosFallidos,
      total_indicadores:
        contactosProcesados + citasRegistradas + negociosCerrados + flujosFallidos,
      latencia_ms: Math.max(0, Date.now() - Date.parse(config.inicio_ejecucion)),
      conclusion: datos.conclusionHipotesis ?? '',
      vd1_reduccion: vd1.porcentajeReduccion ?? 0,
      vd2_reduccion: vd2.porcentajeReduccion ?? 0,
      vd2_diagnostico: vd2Diagnostico.porcentajeReduccion ?? 0,
    },
  },
];
